(6941238, 1046384, 136989, '<td valign="top">I always love how gray skies make colors pop.  Great colors and details in the sand. Awesome shot.</td>', 'I always love how gray skies make colors pop.  Great colors and details in the sand. Awesome shot.', '2012-12-24 14:13:46.000000', NULL, 1),
(6941239, 1046341, 136989, '<td valign="top">This makes me think of elves and fairies.  Great details and beautiful harmony of colors.</td>', 'This makes me think of elves and fairies.  Great details and beautiful harmony of colors.', '2012-12-24 14:14:23.000000', NULL, 1),
(6941240, 1046397, 136989, '<td valign="top">Love the dof and textures on the rusted metal.</td>', 'Love the dof and textures on the rusted metal.', '2012-12-24 14:15:35.000000', NULL, 1),
(6941241, 1046376, 136989, '<td valign="top">Like the concept but not a fan of the blue hue.</td>', 'Like the concept but not a fan of the blue hue.', '2012-12-24 14:17:15.000000', NULL, 1),
(6941242, 1046296, 136989, '<td valign="top">Great texture.  I love the change in directions and how the colors support the leaf imprint.</td>', 'Great texture.  I love the change in directions and how the colors support the leaf imprint.', '2012-12-24 14:18:35.000000', NULL, 1),
(6941243, 1046318, 136989, '<td valign="top">Cool shadow effect and great colors but I''m afraid you''ll be getting the DNMC folks after you.</td>', 'Cool shadow effect and great colors but I''m afraid you''ll be getting the DNMC folks after you.', '2012-12-24 14:19:27.000000', NULL, 1),
(6941244, 1046369, 136989, '<td valign="top">I like the colors in the sky.  I would have cropped out the light top center as it''s distracting. I actually first saw the pic as a square crop from the bottom up and liked it.</td>', 'I like the colors in the sky.  I would have cropped out the light top center as it''s distracting. I actually first saw the pic as a square crop from the bottom up and liked it.', '2012-12-24 14:22:02.000000', NULL, 1),
