(6941250, 1046375, 153374, '<td valign="top">I really love the vibrance of the sunflower and the beautiful detail. If only I can have a lense that can do such wonders. Beautiful job.</td>', 'I really love the vibrance of the sunflower and the beautiful detail. If only I can have a lense that can do such wonders. Beautiful job.', '2012-12-24 14:27:11.000000', NULL, 1),
(6941252, 1046341, 153374, '<td valign="top">Really love the way the roots tell the story. All the perfect highways and and channels that let you know just how much water has given this tree life all those years. One of my favorites.</td>', 'Really love the way the roots tell the story. All the perfect highways and and channels that let you know just how much water has given this tree life all those years. One of my favorites.', '2012-12-24 14:29:39.000000', NULL, 1),
(6941253, 1046362, 153374, '<td valign="top">Beautiful lighting and the different layers of clouds with the pastel colors. Nice shot, so serene.</td>', 'Beautiful lighting and the different layers of clouds with the pastel colors. Nice shot, so serene.', '2012-12-24 14:31:23.000000', NULL, 1),
(6941254, 1045606, 153374, '<td valign="top">Love this shot :) I''m sure there are fossils of life in there.</td>', 'Love this shot :) I''m sure there are fossils of life in there.', '2012-12-24 14:32:53.000000', NULL, 1),
(6941256, 1046402, 153374, '<td valign="top">This is really funny but true in many ways. that witch never had a chance. I still get nightmares of flying monkeys...no Seriously, I do. nice picture.</td>', 'This is really funny but true in many ways. that witch never had a chance. I still get nightmares of flying monkeys...no Seriously, I do. nice picture.', '2012-12-24 14:34:49.000000', NULL, 1),
(6941258, 1045695, 153374, '<td valign="top">Beautiful shot. Love the way the corrosion on the boats shows us the hard work and weather beat down it has endured.</td>', 'Beautiful shot. Love the way the corrosion on the boats shows us the hard work and weather beat down it has endured.', '2012-12-24 14:36:50.000000', NULL, 1),
(6941260, 1046376, 30861, '<td valign="top">My only 10. Conceptually first-rate, and mysterious image to boot. Already voted, commenting now.</td>', 'My only 10. Conceptually first-rate, and mysterious image to boot. Already voted, commenting now.', '2012-12-24 14:37:34.000000', NULL, 1),
