(6941265, 1046067, 30861, '<td valign="top">First-rate B/W conversion, lovely image. To hell with the no-snow-and-no-clouds crowd! 9 from me, and Merry Xmas!</td>', 'First-rate B/W conversion, lovely image. To hell with the no-snow-and-no-clouds crowd! 9 from me, and Merry Xmas!', '2012-12-24 14:40:12.000000', NULL, 1),
