(6941283, 1045695, 54446, '<td valign="top">Meets the challenge very well.  Wonderful weathering/rusting/corrosion.  9</td>', 'Meets the challenge very well.  Wonderful weathering/rusting/corrosion.  9', '2012-12-24 15:56:50.000000', NULL, 1),
(6941284, 1046339, 54446, '<td valign="top">One of my favs in this challenge.  Great idea to show the water-aged buoys.  It''s a fine still life.  Love the weathered colors, which show vestiges of vibrant colors.  Great job! 9</td>', 'One of my favs in this challenge.  Great idea to show the water-aged buoys.  It''s a fine still life.  Love the weathered colors, which show vestiges of vibrant colors.  Great job! 9', '2012-12-24 15:57:00.000000', NULL, 1),
