(6941290, 1046329, 54446, '<td valign="top">While I can''t drink scotch anymore due to declining health, my favorite has always been Talisker.  I absolutely agree with your assessment of the important role of the water.  8</td>', 'While I can''t drink scotch anymore due to declining health, my favorite has always been Talisker.  I absolutely agree with your assessment of the important role of the water.  8', '2012-12-24 16:00:51.000000', NULL, 1),
(6941291, 1046113, 54446, '<td valign="top">Would not have germinated without water.  Good idea.  Nice narrow DOF.</td>', 'Would not have germinated without water.  Good idea.  Nice narrow DOF.', '2012-12-24 16:02:25.000000', NULL, 1),
(6941296, 1046341, 54446, '<td valign="top">While I''m not a fan of such a tall portrait orientation image, I do like the moss covered roots and the "water line".  It''s a dreamy image with attractive splashes of color.</td>', 'While I''m not a fan of such a tall portrait orientation image, I do like the moss covered roots and the "water line".  It''s a dreamy image with attractive splashes of color.', '2012-12-24 16:04:51.000000', NULL, 1),
