(6941299, 1046398, 54446, '<td valign="top">A leap of faith to understand the how.  I like your image very much.  7</td>', 'A leap of faith to understand the how.  I like your image very much.  7', '2012-12-24 16:07:30.000000', NULL, 1),
(6941303, 1046285, 54446, '<td valign="top">Very pleasant silk water effect.   Those moss covered rocks ARE your subject.  I happen to like the context of the stream, but the intolerant voters will not be kind.  9</td>', 'Very pleasant silk water effect.   Those moss covered rocks ARE your subject.  I happen to like the context of the stream, but the intolerant voters will not be kind.  9', '2012-12-24 16:09:38.000000', NULL, 1),
